INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT144-S4-Q6$batch13$, 144, 4, 6, $batch13$Parallel Flaw$batch13$, $batch13$If one is to participate in the regional band, one must practice very hard or be very talented. Therefore, Lily, who is first trombonist in the regional band and is very talented, does not practice hard.$batch13$, $batch13$The flawed reasoning in which one of the following arguments most closely resembles the flawed reasoning in the argument above?$batch13$, $batch13$D$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=144 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q6$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$In order to have a chance to meet its objectives, the army needs good weather as a precondition for retaining its mobility. The weather is good today, so the army will meet its objectives.$batch13$, $batch13$Different Flaw$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$If Lois were on vacation, she would be visiting her brother in Chicago or seeing friends in Toronto. Since she is not on vacation, she is in neither Chicago nor Toronto.$batch13$, $batch13$Different Flaw$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$If Johnson is to win the local election, then neither Horan nor Jacobs can enter the race. Since neither of them plans to run, Johnson will win the race.$batch13$, $batch13$Different Flaw$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$To stay informed about current events, one must read a major newspaper or watch national TV news every day. So Julie, who is informed about current events and reads a major newspaper every day, does not watch TV news.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$If Wayne is to get a ride home from the library, either Yvette or Marty must be there. Yvette is not at the library, so Marty must be there.$batch13$, $batch13$Different Flaw$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Lily doesn't practice hard.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$To be in the regional band, one must practice very hard or be very talented. Lily is in the band and is very talented.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$"Or" means at least one, not only one. Lily's talent satisfies the requirement, but that doesn't rule out practicing hard too. The flaw: treating "or" as "one but not both".$batch13$), (3, $batch13$Goal$batch13$, $batch13$Find an argument that sees one half of an "or" condition met and concludes the other half isn't.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$This treats a requirement (good weather) as a guarantee of success. There's no "or".$batch13$), ($batch13$B$batch13$, $batch13$This assumes that because Lois isn't on vacation, the outcome tied to vacation can't happen. It's a different error.$batch13$), ($batch13$C$batch13$, $batch13$This treats a requirement for winning as enough to win.$batch13$), ($batch13$D$batch13$, $batch13$Julie meets one half of the "or" by reading a newspaper, and the argument concludes Julie doesn't watch TV news. Same error.$batch13$), ($batch13$E$batch13$, $batch13$This assumes Wayne gets a ride, which nothing says. Its "or" reasoning is valid: if one option is gone and at least one is needed, the other must hold.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT144-S4-Q6$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
